const numIslands = (grid) => {
  const rowsCount = grid.length;
  const columnsCount = grid[0].length;
  let result = 0;

  const dfs = (row, col) => {
    if (row < 0
      || row >= rowsCount
      || col < 0
      || col >= columnsCount
      || grid[row][col] === '0'
    ) {
      return;
    }

    grid[row][col] = '0';

    dfs(row + 1, col);    
    dfs(row - 1, col);
    dfs(row, col + 1);
    dfs(row, col - 1);
  };

  for (let row = 0; row < rowsCount; row++) {
    for (let col = 0; col < columnsCount; col++) {
      if (grid[row][col] === '1') {
        result++;
        dfs(row, col);
      }
    }
  }

  return result;
};

