const partitionLabels = (s) => {
  const CharToLastIndex = {};

  for (let i = 0; i < s.length; i++) {
    CharToLastIndex[s[i]] = i;
  }

  const result = [];
  let size = 0;
  let end = 0;

  for (let i = 0; i < s.length; i++) {
    size++;
    end = Math.max(end, CharToLastIndex[s[i]]);

    if (i === end) {
      result.push(size);
      size = 0;
    }
  }

  return result;
};

