const maxSubArray = (nums) => {
  let maxSum = -Infinity;
  let currentSum = 0;

  for (const num of nums) {
    currentSum = Math.max(currentSum, 0) + num;
    maxSum = Math.max(maxSum, currentSum);
  }

  return maxSum;
};

