const pairSum = (head) => {
  let slow = head;
  let fast = head;
  let prev = null;
  let result = 0;

  while (fast?.next) {
    fast = fast.next.next;
    [slow.next, prev, slow] = [prev, slow, slow.next];
  }

  while (slow) {
    result = Math.max(result, prev.val + slow.val);
    prev = prev.next;
    slow = slow.next;
  }

  return result;
};

