const rob = (nums) => {
  const helper = (start, end) => {
    let rob1 = 0;
    let rob2 = 0;

    for (let i = start; i < end; i++) {      
      [rob1, rob2] = [rob2, Math.max(rob1 + nums[i], rob2)];
    }

    return rob2;
  };

  return Math.max(nums[0], helper(0, nums.length - 1), helper(1, nums.length));
};

