console.log(characterReplacement('AABABBA', 1)); // 4`,difficulty:`medium`,id:`longest-repeating-character-replacement`,link:`https://leetcode.com/problems/longest-repeating-character-replacement/`,name:`Longest Repeating Character Replacement`,subject:`sliding-window`,tags:[P.HASH_TABLE,P.STRING,P.SLIDING_WINDOW]},{code:`// Время O(n), память O(1)
const checkInclusion = (s1, s2) => {
  if (s1.length > s2.length) {
    return false;
  }

  const s1Count = Array(26).fill(0);
  const s2Count = Array(26).fill(0);

  for (let i = 0; i < s1.length; i++) {
    s1Count[s1[i].charCodeAt() - 'a'.charCodeAt()]++;
    s2Count[s2[i].charCodeAt() - 'a'.charCodeAt()]++;
  }

  let matches = 0;

  for (let i = 0; i < 26; i++) {
    if (s1Count[i] === s2Count[i]) {
      matches++;
    }
  }

  let left = 0;

  for (let right = s1.length; right < s2.length; right++) {
    if (matches === 26) {
      return true;
    }

    let index = s2[right].charCodeAt() - 'a'.charCodeAt();
    s2Count[index]++;

    if (s1Count[index] === s2Count[index]) {
      matches++;
    } else if (s1Count[index] + 1 === s2Count[index]) {
      matches--;
    }

    index = s2[left].charCodeAt() - 'a'.charCodeAt();
    s2Count[index]--;

    if (s1Count[index] === s2Count[index]) {
      matches++;
    } else if (s1Count[index] - 1 === s2Count[index]) {
      matches--;
    }

    left++;
  }

  return matches === 26;
};

console.log(checkInclusion('ab', 'eidbaooo')); // true
console.log(checkInclusion('ab', 'eidboaoo')); // false`,difficulty:`medium`,id:`permutation-in-string`,link:`https://leetcode.com/problems/permutation-in-string/`,name:`Permutation in String`,subject:`sliding-window`,tags:[P.HASH_TABLE,P.TWO_POINTERS,P.STRING,P.SLIDING_WINDOW]},{difficulty:`hard`,id:`minimum-window-substring`,link:`https://leetcode.com/problems/minimum-window-substring/`,name:`Minimum Window Substring`,subject:`sliding-window`,tags:[P.HASH_TABLE,P.STRING,P.SLIDING_WINDOW]},{difficulty:`hard`,id:`sliding-window-maximum`,link:`https://leetcode.com/problems/sliding-window-maximum/`,name:`Sliding Window Maximum`,subject:`sliding-window`,tags:[P.ARRAY,P.QUEUE,P.SLIDING_WINDOW,P.HEAP,P.MONOTONIC_QUEUE]}],wa=[{code:`// Время O(n ∗ log n), память O(n)
const sortArray = (nums) => {
  const quickSort = (nums, start, end) => {
    if (end - start + 1 <= 1) {
      return nums;
    }

    const pivot = nums[Math.round(Math.random() * (end - start) + start)];

    let left = start;
    let right = end;

    while (left <= right) {
      while (nums[left] < pivot) {
        left++;
      }

      while (nums[right] > pivot) {
        right--;
      }

      if (left <= right) {
        [nums[right], nums[left]] = [nums[left], nums[right]];
        left++;
        right--;
      }
    }

    quickSort(nums, start, right);
    quickSort(nums, left, end);

    return nums;
  };

  return quickSort(nums, 0, nums.length - 1);
};

console.log(sortArray([5, 2, 3, 1])); // [1, 2, 3, 5]
