const kthSmallest = (root, k) => {
  const stack = [];
  let n = 0;
  let cur = root;

  while (cur || stack.length) {
    while (cur) {
      stack.push(cur);
      cur = cur.left;
    }

    cur = stack.pop();
    n++;
    
    if (n === k) {
      return cur.val;
    }

    cur = cur.right;
  }
};

