const lowestCommonAncestor = (root, p, q) => {
  let cur = root;

  while (cur) {
    if (p > cur.val && q > cur.val) {
      cur = cur.right;
    } else if (p < cur.val && q < cur.val) {
      cur = cur.left;
    } else {    
      return cur;
    }
  }
};

