const goodNodes = (root) => {
  const dfs = (node, maxVal) => {
    if (!node) {
      return 0;
    }

    let result = node.val >= maxVal ? 1 : 0;
    maxVal = Math.max(maxVal, node.val);
    result += dfs(node.left, maxVal);
    result += dfs(node.right, maxVal);
    return result;
  };

  return dfs(root, root.val);
};

