const isValidBST = (root) => {
  const valid = (node, left, right) => {
    if (!node) {
      return true;
    }

    if (!(node.val < right && node.val > left)) {
      return false;
    }

    return valid(node.left, left, node.val) && valid(node.right, node.val, right);
  }

  return valid(root, -Infinity, Infinity);
};

